#include <string>
#include <vector>

class Solution {
public:
    long long countMagicalPairs(std::string s) {
        int n = s.size();
        long long total = 0;
        for (int j = 0; j < n - 1; ++j) {
            int left[27] = {0}, right[27] = {0};
            int mask = 0;
            for (int i = j; i >= 0; --i) {
                mask |= (1 << (s[i] - 'a'));
                left[__builtin_popcount(mask)]++;
            }
            mask = 0;
            for (int k = j + 1; k < n; ++k) {
                mask |= (1 << (s[k] - 'a'));
                right[__builtin_popcount(mask)]++;
            }
            for (int d = 1; d <= 26; ++d) total += (long long)left[d] * right[d];
        }
        return total;
    }
};

class Solution {
    public long countMagicalPairs(String s) {
        int n = s.length();
        long total = 0;
        for (int j = 0; j < n - 1; j++) {
            int[] left = new int[27];
            int[] right = new int[27];
            int mask = 0;
            for (int i = j; i >= 0; i--) {
                mask |= 1 << (s.charAt(i) - 'a');
                left[Integer.bitCount(mask)]++;
            }
            mask = 0;
            for (int k = j + 1; k < n; k++) {
                mask |= 1 << (s.charAt(k) - 'a');
                right[Integer.bitCount(mask)]++;
            }
            for (int d = 1; d <= 26; d++) total += (long) left[d] * right[d];
        }
        return total;
    }
}

var countMagicalPairs = function(s) {
    const n = s.length;
    let total = 0;
    const popcount = (x) => {
        let count = 0;
        while (x > 0) { count += x & 1; x >>= 1; }
        return count;
    };
    for (let j = 0; j < n - 1; j++) {
        const left = new Int32Array(27);
        const right = new Int32Array(27);
        let mask = 0;
        for (let i = j; i >= 0; i--) {
            mask |= 1 << (s.charCodeAt(i) - 97);
            left[popcount(mask)]++;
        }
        mask = 0;
        for (let k = j + 1; k < n; k++) {
            mask |= 1 << (s.charCodeAt(k) - 97);
            right[popcount(mask)]++;
        }
        for (let d = 1; d <= 26; d++) total += left[d] * right[d];
    }
    return total;
};
